from flask import Blueprint, render_template, request, redirect, url_for
from app.models.note import Note
from app.database import db

notes_bp = Blueprint('notes', __name__)

@notes_bp.route('/')
def index():
    notes = Note.query.all()  # Retrieve all notes from the database
    return render_template('index.html', notes=notes)

@notes_bp.route('/add', methods=['POST'])
def add_note():
    note_content = request.form.get('content')
    if note_content:
        new_note = Note(content=note_content)
        db.session.add(new_note)
        db.session.commit()
    return redirect(url_for('notes.index'))

@notes_bp.route('/delete/<int:note_id>', methods=['POST'])
def delete_note(note_id):
    note_to_delete = Note.query.get(note_id)
    if note_to_delete:
        db.session.delete(note_to_delete)
        db.session.commit()
    return redirect(url_for('notes.index'))

/* static/styles.css */
/* Styles for the Note-Taking Interface */

/* General Body Styling */
body {
    font-family: Arial, sans-serif;
    background-color: #f8f9fa;
    margin: 0;
    padding: 0;
}

/* Container for the Note-Taking App */
.container {
    max-width: 800px;
    margin: 50px auto;
    padding: 20px;
    background-color: #ffffff;
    border-radius: 8px;
    box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
}

/* Header Styling */
header {
    text-align: center;
    margin-bottom: 20px;
}

header h1 {
    font-size: 2.5rem;
    color: #343a40;
}

/* Form Styling */
form {
    display: flex;
    flex-direction: column;
    gap: 15px;
    margin-bottom: 30px;
}

form input[type="text"] {
    padding: 10px;
    font-size: 1.1rem;
    border: 1px solid #ced4da;
    border-radius: 4px;
}

form input[type="text"]:focus {
    outline: none;
    border-color: #007bff;
    box-shadow: 0 0 4px rgba(0, 123, 255, 0.3);
}

form button {
    padding: 10px 15px;
    font-size: 1.1rem;
    color: #ffffff;
    background-color: #007bff;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

form button:hover {
    background-color: #0056b3;
}

/* Notes List Styling */
.notes {
    list-style: none;
    padding: 0;
}

.notes li {
    background-color: #e9ecef;
    margin-bottom: 10px;
    padding: 10px;
    border-radius: 4px;
    font-size: 1rem;
    color: #495057;
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.notes li span {
    flex: 1;
    word-wrap: break-word;
}

.notes li button {
    padding: 5px 10px;
    font-size: 0.9rem;
    color: #ffffff;
    background-color: #dc3545;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

.notes li button:hover {
    background-color: #c82333;
}

from flask import Flask
from app.database import db
from app.routes import notes_bp

def create_app():
    app = Flask(__name__)
    app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///notes.db'
    app.config['SECRET_KEY'] = 'your_secret_key'

    db.init_app(app)
    app.register_blueprint(notes_bp)

    @app.before_first_request
    def create_tables():
        db.create_all()

    @app.route('/')
    def home():
        return "Welcome to the Note-Taking App!"

    return app

